const body = $json.body ?? $json;
const repoUrl = body.repo_url || body.repository_url || '';
if (!repoUrl) {
  throw new Error('Missing repo_url. Send the GitHub repository URL in the request body.');
}
const githubData = body.github_data ?? {};
const discordData = body.discord_data ?? {};
const extraContext = body.extra_context ?? '';
const prompt = `You are RepoBloom, an evidence-first project handoff assistant. Analyze only the supplied evidence. Do not invent contributor roles, implementation status, tests, metrics, or decisions. Distinguish facts from inferences and unknowns. For contributors, explain specific files/commits and the evidence behind each inferred work area; do not claim a formal job title unless explicitly supported. Explain important commits in plain language, what appears completed, what was attempted, what remains unclear, and suggested next steps. Cite commit SHAs, file paths, timestamps, or Discord messages where available.

Repository: ${repoUrl}

GitHub evidence:
${JSON.stringify(githubData).slice(0, 50000)}

Discord evidence:
${JSON.stringify(discordData).slice(0, 30000)}

Additional context:
${String(extraContext).slice(0, 10000)}

Return a concise, structured JSON object with keys: project_overview, contributors (array), important_commits (array), decisions_and_attempts (array), completed_work (array), pending_or_unclear (array), recommended_handoff (array), evidence_gaps (array). Each nontrivial claim should include evidence and confidence where possible.`;
return [{ json: { repo_url: repoUrl, prompt, model: body.model || 'qwen/qwen3.7-plus' } }];

const response = $json;
const content = response.choices?.[0]?.message?.content;
if (!content) {
  return [{ json: { ok: false, error: 'LLM response did not contain message content.', provider_response: response } }];
}
let analysis;
try {
  const cleaned = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  analysis = JSON.parse(cleaned);
} catch (e) {
  analysis = { raw_analysis: content, parse_warning: 'Model response was not valid JSON; inspect raw_analysis.' };
}
return [{ json: { ok: true, source: 'n8n', analysis } }];
